  insert into content.hadith_entries
    (collection_id, number, arabic_text, translation_translations, grading, benefit_note_translations, source, source_dataset, review_status, reviewed_by, reviewed_at, published)
  values
    (col_id, 1, 'عَنْ أَبِي هُرَيْرَةَ - ﵁ - قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ - فِي الْبَحْرِ: «هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ» أَخْرَجَهُ الْأَرْبَعَةُ، وَابْنُ أَبِي شَيْبَةَ وَاللَّفْظُ لَهُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَالتِّرْمِذِيُّ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 2, 'وَعَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ - ﵁ - قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «إِنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ» أَخْرَجَهُ الثَّلَاثَةُ، وَصَحَّحَهُ أَحْمَدُ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 3, 'وَعَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ - ﵁ - قَالَ: قَالَ رَسُولُ اللهِ - ﷺ -: «إِنَّ الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ، إِلَّا مَا غَلَبَ عَلَى رِيحِهِ وَطَعْمِهِ وَلَوْنِهِ» أَخْرَجَهُ ابْنُ مَاجَهْ وَضَعَّفَهُ أَبُو حَاتِمٍ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 4, 'وَلِلْبَيْهَقِيِّ: «الْمَاءُ طَهُورٌ إِلَّا إِنْ تَغَيَّرَ رِيحُهُ، أَوْ طَعْمُهُ، أَوْ لَوْنُهُ; بِنَجَاسَةٍ تَحْدُثُ فِيهِ».', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 5, 'وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ ﵄ قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلِ الْخَبَثَ»، وَفِي لَفْظٍ: «لَمْ يَنْجُسْ» أَخْرَجَهُ الْأَرْبَعَةُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ حِبَّانَ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 6, 'وَعَنْ أَبِي هُرَيْرَةَ - ﵁ - قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «لا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَهُوَ جُنُبٌ» أَخْرَجَهُ مُسْلِمٌ، وَلِلْبُخَارِيِّ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ الَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ فِيهِ»، وَلِمُسْلِمٍ: «مِنْهُ»، وَلِأَبِي دَاوُدَ: «وَلَا يَغْتَسِلُ فِيهِ مِنَ الْجَنَابَةِ».', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 7, 'وَعَنْ رَجُلٍ صَحِبَ النَّبِيَّ - ﷺ - قَالَ: نَهَى رَسُولُ اللَّهِ - ﷺ - أَنْ تَغْتَسِلَ الْمَرْأَةُ بِفَضْلِ الرَّجُلِ، أَوِ الرَّجُلُ بِفَضْلِ الْمَرْأَةِ، وَلْيَغْتَرِفَا جَمِيعًا. أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَإِسْنَادُهُ صَحِيحٌ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 8, 'وَعَنِ ابْنِ عَبَّاسٍ ﵄، أَنَّ النَّبِيَّ - ﷺ - كَانَ يَغْتَسِلُ بِفَضْلِ مَيْمُونَةَ ﵂. أَخْرَجَهُ مُسْلِمٌ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 9, 'وَلِأَصْحَابِ السُّنَنِ: اغْتَسَلَ بَعْضُ أَزْوَاجِ النَّبِيِّ - ﷺ - فِي جَفْنَةٍ، فَجَاءَ لِيَغْتَسِلَ مِنْهَا، فَقَالَتْ لَهُ: إِنِّي كُنْتُ جُنُبًا، فَقَالَ: «إِنَّ الْمَاءَ لَا يُجْنِبُ» وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ خُزَيْمَةَ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 10, 'وَعَنْ أَبِي هُرَيْرَةَ - ﵁ - قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «طُهُورُ إِنَاءِ أَحَدِكُمْ إِذَا وَلَغَ فِيهِ الْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ» أَخْرَجَهُ مُسْلِمٌ، وَفِي لَفْظٍ لَهُ: «فَلْيُرِقْهُ». وَلِلتِّرْمِذِيِّ: «أُخْرَاهُنَّ، أَوْ أُولَاهُنَّ بِالتُّرَابِ».', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 11, 'وَعَنْ أَبِي قَتَادَةَ - ﵁ - أَنَّ رَسُولَ اللَّهِ - ﷺ - قَالَ -فِي الْهِرَّةِ-: «إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنَ الطَّوَّافِينَ عَلَيْكُمْ» أَخْرَجَهُ الْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ خُزَيْمَةَ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 12, 'وَعَنْ أَنَسِ بْنِ مَالِكٍ - ﵁ - قَالَ: جَاءَ أَعْرَابِيٌّ فَبَالَ فِي طَائِفَةِ الْمَسْجِدِ، فَزَجَرَهُ النَّاسُ، فَنَهَاهُمُ النَّبِيُّ - ﷺ - فَلَمَّا قَضَى بَوْلَهُ أَمَرَ النَّبِيُّ - ﷺ - بِذَنُوبٍ مِنْ مَاءٍ; فَأُهْرِيقَ عَلَيْهِ. مُتَّفَقٌ عَلَيْهِ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 13, 'وَعَنِ ابْنِ عُمَرَ ﵄ قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ، فَأَمَّا الْمَيْتَتَانِ: فَالْجَرَادُ وَالْحُوتُ، وَأَمَّا الدَّمَانِ: فَالطِّحَالُ وَالْكَبِدُ» أَخْرَجَهُ أَحْمَدُ وَابْنُ مَاجَهْ، وَفِيهِ ضَعْفٌ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 14, 'وَعَنْ أَبِي هُرَيْرَةَ - ﵁ - قَالَ: قَالَ رَسُولُ اللَّهِ - ﷺ -: «إِذَا وَقَعَ الذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ، ثُمَّ ليَنْزِعْهُ، فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً، وَفِي الْآخَرِ شِفَاءً» أَخْرَجَهُ الْبُخَارِيُّ، وَأَبُو دَاوُدَ، وَزَادَ: «وَإِنَّهُ يَتَّقِي بِجَنَاحِهِ الَّذِي فِيهِ الدَّاءُ».', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 15, 'وَعَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ - ﵁ - قَالَ: قَالَ النَّبِيُّ - ﷺ -: «مَا قُطِعَ مِنَ الْبَهِيمَةِ -وَهِيَ حَيَّةٌ- فَهُوَ مَيِّتٌ» أَخْرَجَهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَحَسَّنَهُ، وَاللَّفْظُ لَهُ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 16, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ ﵄، قَالَ: قَالَ رَسُولُ اللهِ - ﷺ -: «لَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ والْفِضَّةِ، وَلَا تَأْكُلُوا فِي صِحَافِهَا، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا، وَلَكُمْ فِي الْآخِرَةِ» مُتَّفَقٌ عَلَيْهِ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 17, 'وَعَنْ أُمِّ سَلَمَةَ ﵂، قَالَتْ: قَالَ رَسُولُ الْلَّهِ - ﷺ -: «الَّذِي يَشْرَبُ فِي إِنَاءِ الْفِضَّةِ إِنَّمَا يُجَرْجِرُ فِي بَطْنِهِ نَارَ جَهَنَّمَ» مُتَّفَقٌ عَلَيْهِ.', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
    (col_id, 18, 'وَعَنِ ابْنِ عَبَّاسٍ ﵄ قَالَ: قَالَ رَسُولُ الْلَّهِ - ﷺ -: «إِذَا دُبِغَ الْإِهَابُ فَقَدْ طَهُرَ» أَخْرَجَهُ مُسْلِمٌ، وَعِنْدَ الْأَرْبَعَةِ: «أَيُّمَا إِهَابٍ دُبِغَ».', '{}'::jsonb, '', '{}'::jsonb, 'المكتبة الشاملة / turath.io — بلوغ المرام من أدلة الأحكام، ت. ماهر ياسين الفحل (كتاب رقم 17757)', 'Shamela/turath.io #17757 — بلوغ المرام، ت. ماهر ياسين الفحل (Arabic matn only)', 'pending', null, null, false),
